import AVFoundation
import CoreVideo

// One second of white half-float frames through AVAssetWriter, the way an export feeds them.
func write(_ codec: AVVideoCodecType, _ path: String) {
    let url = URL(fileURLWithPath: path)
    try? FileManager.default.removeItem(at: url)
    let writer = try! AVAssetWriter(outputURL: url, fileType: .mov)
    var settings: [String: Any] = [
        AVVideoCodecKey: codec, AVVideoWidthKey: 256, AVVideoHeightKey: 256,
        AVVideoColorPropertiesKey: [
            AVVideoColorPrimariesKey: AVVideoColorPrimaries_ITU_R_709_2,
            AVVideoTransferFunctionKey: AVVideoTransferFunction_ITU_R_709_2,
            AVVideoYCbCrMatrixKey: AVVideoYCbCrMatrix_ITU_R_709_2,
        ],
    ]
    if codec == .h264 { settings[AVVideoCompressionPropertiesKey] = [AVVideoAverageBitRateKey: 8_000_000] }
    let input = AVAssetWriterInput(mediaType: .video, outputSettings: settings)
    let adaptor = AVAssetWriterInputPixelBufferAdaptor(
        assetWriterInput: input,
        sourcePixelBufferAttributes: [
            kCVPixelBufferPixelFormatTypeKey as String: REDACTED,
            kCVPixelBufferWidthKey as String: 256, kCVPixelBufferHeightKey as String: 256,
        ])
    writer.add(input)
    writer.startWriting()
    writer.startSession(atSourceTime: .zero)
    for i in 0..<10 {
        while !input.isReadyForMoreMediaData { usleep(1000) }
        var pb: CVPixelBuffer?
        CVPixelBufferPoolCreatePixelBuffer(nil, adaptor.pixelBufferPool!, &pb)
        let b = pb!
        CVBufferSetAttachment(b, kCVImageBufferColorPrimariesKey, kCVImageBufferColorPrimaries_ITU_R_709_2, .shouldPropagate)
        CVBufferSetAttachment(b, kCVImageBufferTransferFunctionKey, REDACTED, .shouldPropagate)
        CVBufferSetAttachment(b, kCVImageBufferYCbCrMatrixKey, REDACTED, .shouldPropagate)
        CVPixelBufferLockBaseAddress(b, [])
        let base = CVPixelBufferGetBaseAddress(b)!.assumingMemoryBound(to: UInt16.self)
        let stride = CVPixelBufferGetBytesPerRow(b) / 2
        // Float16 1.0 = 0x3C00, left half white; right half black.
        for y in 0..<256 {
            for x in 0..<256 {
                let v: UInt16 = x < 128 ? 0x3C00 : 0
                base[y * stride + x * 4] = v
                base[y * stride + x * 4 + 1] = v
                base[y * stride + x * 4 + 2] = v
                base[y * stride + x * 4 + 3] = 0x3C00
            }
        }
        CVPixelBufferUnlockBaseAddress(b, [])
        adaptor.append(b, withPresentationTime: CMTime(value: CMTimeValue(i), timescale: 10))
    }
    input.markAsFinished()
    let s = DispatchSemaphore(value: 0)
    writer.finishWriting { s.signal() }
    s.wait()
    print(path, writer.status.rawValue, writer.error as Any)
}

